package cn.kaoyan.assistant;
import org.json.*;import java.io.*;import java.util.*;import java.nio.charset.StandardCharsets;
final class FullBackup {
 private static final Set<String> active=Collections.synchronizedSet(new HashSet<String>());
 final File root,attachments;final Map<String,File> staged=new HashMap<>();
 FullBackup(File root){this.root=root;attachments=new File(root,"attachments");attachments.mkdirs();File[] leftovers=root.listFiles();if(leftovers!=null)for(File dir:leftovers)if(dir.isDirectory()&&dir.getName().matches("restore-[a-f0-9-]{36}")&&!active.contains(dir.getAbsolutePath()))ArchiveIO.remove(dir);}
 static String safe(String path)throws IOException{ArchiveIO.validate("attachments/"+path);return path;}
 void export(OutputStream out,JSONObject state)throws Exception{Map<String,File> originals=new LinkedHashMap<>();JSONArray files=state.getJSONArray("files");for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);String path=f.optString("path");File source=new File(attachments,safe(path));if(!source.isFile())throw new IOException("原件缺失："+f.optString("name")+"，可先导出轻量备份");originals.put(path,source);f.put("size",source.length()).put("sha256",FileDigest.sha256(source)).put("missing",false);}state.put("fullBackup",1);ArchiveIO.write(out,state.toString().getBytes(StandardCharsets.UTF_8),originals);}
 JSONObject prepare(InputStream in)throws Exception{String token=UUID.randomUUID().toString();File stage=new File(root,"restore-"+token);active.add(stage.getAbsolutePath());try{JSONObject state=new JSONObject(new String(ArchiveIO.stage(in,stage,()->root.getUsableSpace()),StandardCharsets.UTF_8));if(state.optInt("schema")!=1)throw new IOException("不支持的学习备份版本");JSONArray files=state.getJSONArray("files");for(String k:Arrays.asList("tasks","notes","mistakes"))state.getJSONArray(k);Set<String> ids=new HashSet<>();for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);if(!ids.add(f.getString("id")))throw new IOException("备份资料ID重复");String path=safe(f.getString("path"));File source=new File(stage,"attachments/"+path);if(!source.isFile()||source.length()!=f.getLong("size")||!FileDigest.sha256(source).equals(f.optString("sha256")))throw new IOException("原件完整性检查未通过："+f.optString("name"));}staged.put(token,stage);return new JSONObject().put("token",token).put("state",state).put("fileCount",files.length());}catch(Exception e){active.remove(stage.getAbsolutePath());ArchiveIO.remove(stage);throw e;}}
 void discard(String token){File dir=staged.remove(token);if(dir!=null){active.remove(dir.getAbsolutePath());ArchiveIO.remove(dir);}}
 interface StateWriter{void write(JSONObject state)throws Exception;}
 JSONObject commit(String token,JSONObject state,StateWriter writer)throws Exception{File dir=staged.get(token);if(dir==null)throw new IOException("恢复预览已失效，请重新选择备份");JSONObject original;try(InputStream in=new FileInputStream(new File(dir,"state.json"))){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);original=new JSONObject(out.toString("UTF-8"));}JSONArray old=original.getJSONArray("files"),files=state.getJSONArray("files");if(old.length()!=files.length())throw new IOException("恢复目录不匹配");Map<String,JSONObject> indexed=new HashMap<>();for(int i=0;i<old.length();i++)indexed.put(old.getJSONObject(i).getString("id"),old.getJSONObject(i));List<File> installed=new ArrayList<>();Map<String,File> restoredSources=new HashMap<>();try{for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i),source=indexed.get(f.getString("id"));if(source==null)throw new IOException("恢复文件ID无效");String path=safe(source.getString("path")),ext=path.contains(".")?path.substring(path.lastIndexOf('.')):".bin",name="restored-"+UUID.randomUUID()+ext;File input=restoredSources.containsKey(path)?restoredSources.get(path):new File(dir,"attachments/"+path),destination=new File(attachments,safe(name));if(!input.isFile()||!FileDigest.sha256(input).equals(source.getString("sha256")))throw new IOException("恢复原件已变化");installed.add(destination);if(restoredSources.containsKey(path)){if(root.getUsableSpace()<input.length()+AttachmentTransfer.RESERVE_BYTES)throw new IOException("空间不足，恢复已取消");java.nio.file.Files.copy(input.toPath(),destination.toPath());}else{if(!input.renameTo(destination))throw new IOException("无法安装恢复原件");restoredSources.put(path,destination);}f.put("path",name).put("size",destination.length()).put("sha256",source.getString("sha256")).put("missing",false).put("body",source.optString("body")).put("pages",source.optJSONArray("pages")==null?new JSONArray():source.getJSONArray("pages")).put("status",source.optString("status","saved")).put("textInNotes",source.optBoolean("textInNotes")).put("pageCount",Math.max(source.optInt("pageCount"),source.optInt("totalPages")));}state.remove("pendingFileDeletes");writer.write(state);discard(token);return state;}catch(Exception e){for(File f:installed)f.delete();discard(token);throw e;}}
}
